import{_ as p,a0 as d,w as o,s as n,ao as e,I as a,x as r,a1 as l,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"樹莓派 3 還是 4：你應該買哪一個？ | LCTT x X-CMD","titleTemplate":false,"description":"樹莓派 3 還是 4：你應該買哪一個？ | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"樹莓派 3 還是 4：你應該買哪一個？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"樹莓派 3 還是 4：你應該買哪一個？ | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211118 Raspberry Pi 3 vs 4- Which One Should You Get","title":"樹莓派 3 還是 4：你應該買哪一個？","tag":"202111","desc":""},"relativePath":"202111/20211118 Raspberry Pi 3 vs 4- Which One Should You Get.md","filePath":"[post].md"}'),m={name:"202111/20211118 Raspberry Pi 3 vs 4- Which One Should You Get.md"};function u(h,t,S,B,f,C){const i=d("Link");return o(),n("div",null,[t[21]||(t[21]=e('<h1 id="樹莓派-3-還是-4-你應該買哪一個" tabindex="-1">樹莓派 3 還是 4：你應該買哪一個？ <a class="header-anchor" href="#樹莓派-3-還是-4-你應該買哪一個" aria-label="Permalink to “樹莓派 3 還是 4：你應該買哪一個？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202111/18/171924sg0bk3iu43bwi3x4.jpg" alt=""></p><p>樹莓派是一種物美價廉的單板計算機，在很多場景都很有用。不過，在樹莓派 4 之前，它作為快速的桌面替代品並不是一個特別合適的選擇。</p><p>所以，樹莓派 4 以其新的功能改變了遊戲規則。但是，它與樹莓派 3 相比如何？</p><p>樹莓派 3 仍然值得考慮嗎？或者，你應該去買最新和更強大的樹莓派 4？</p><p>在這篇文章中，我們試圖通過強調兩者之間的一些關鍵差異來為你提供一些答案。</p><p>首先，讓我們看一下兩者提供的規格：</p><h3 id="樹莓派-3-的規格" tabindex="-1">樹莓派 3 的規格 <a class="header-anchor" href="#樹莓派-3-的規格" aria-label="Permalink to “樹莓派 3 的規格”">​</a></h3><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/raspberry-pi-3.jpg?resize=800%2C534&amp;ssl=1" alt=""></p>',9)),a("p",null,[t[1]||(t[1]=r("樹莓派 3 滿足了一個基本入門 DIY 項目的所有要求。如果 ",-1)),l(i,{href:"https://itsfoss.com/raspberry-pi-zero-vs-zero-w/"},{default:s(()=>[...t[0]||(t[0]=[r("樹莓派 Zero 或 樹莓派 Zero W",-1)])]),_:1}),t[2]||(t[2]=r(" 不符合你的要求，那麼樹莓派 3 是一個物美價廉的選擇：",-1))]),t[22]||(t[22]=e('<ul><li>四核 1.2GHz 博通 BCM2837 64 位 CPU</li><li>1GB 內存</li><li>無線局域網和低功耗藍牙（BLE）</li><li>以太網</li><li>40 針擴展 GPIO</li><li>4 個 USB 2 端口</li><li>4 極立體聲輸出和複合視頻端口</li><li>全尺寸的 HDMI</li><li>CSI 攝像機端口</li><li>DSI 顯示端口</li><li>用於操作系統和存儲數據的微型 SD 端口</li><li>升級後的開關式微型 USB 電源，最高可達 2.5A 電流</li></ul><h3 id="樹莓派-4-的規格" tabindex="-1">樹莓派 4 的規格 <a class="header-anchor" href="#樹莓派-4-的規格" aria-label="Permalink to “樹莓派 4 的規格”">​</a></h3><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/09/raspberry-pi-4.jpg?resize=583%2C340&amp;ssl=1" alt=""></p><ul><li>博通 BCM2711，四核 Cortex-A72（ARM v8）64 位 SoC @ 1.5GHz</li><li>2GB、4GB 或 8GB LPDDR4-3200</li><li>2.4 GHz 和 5.0 GHz IEEE 802.11ac 無線，藍牙 5.0，BLE</li><li>千兆位以太網</li><li>2 個 USB 3.0 端口</li><li>2 個 USB 2.0 端口</li><li>40 針 GPIO 接頭（向後兼容）</li><li>2 個微型 HDMI 端口（最多可支持 4kp60）</li><li>2 線 MIPI DSI 顯示端口</li><li>2 線 MIPI CSI 攝像頭端口</li><li>4 極立體聲音頻和複合視頻端口</li><li>H.265（4kp60 解碼），H264（1080p60 解碼，1080p30 編碼）</li><li>OpenGL ES 3.1，Vulkan 1.0</li><li>用於操作系統和存儲數據的 MicroSD 卡插槽</li><li>通過 USB-C 接口的 5V 直流電</li><li>通過 GPIO 接頭的 5V 直流電</li><li>通過以太網供電</li></ul><h3 id="內存-ram-選項" tabindex="-1">內存（RAM）選項 <a class="header-anchor" href="#內存-ram-選項" aria-label="Permalink to “內存（RAM）選項”">​</a></h3><p>對於樹莓派機型，通常情況下，你會得到一個包括 1 或 2GB 內存的單一產品陣容。</p><p>樹莓派 3B+ 就是這種情況。如果你不需要更多的內存，樹莓派 3 可以就是一個不錯的解決方案，可以滿足所有常規 DIY 項目的需求。</p><p>然而，對於樹莓派 4，你可以選擇 2GB、4GB 和 8GB 的版本。所以，如果你想完成更多的事情，或者在你的樹莓派板上實現多個任務，樹莓派 4 應該是一個不錯的選擇。</p><h3 id="性能差異" tabindex="-1">性能差異 <a class="header-anchor" href="#性能差異" aria-label="Permalink to “性能差異”">​</a></h3><p>儘管這兩塊板子都採用了博通公司的芯片，但樹莓派 4 的性能明顯更快。</p><p>如果你想把它作為你的迷你桌面的替代品，或者想為你的任務獲得更好的計算能力，樹莓派 4 將是明顯的選擇。</p><p>説到樹莓派 3，它配備了一個四核 1.2GHz 的博通 BCM2837 64 位 CPU。它是一個能夠完成各種任務的芯片。</p><h4 id="連接能力" tabindex="-1">連接能力 <a class="header-anchor" href="#連接能力" aria-label="Permalink to “連接能力”">​</a></h4><p>兩塊樹莓派板都提供了一個 40 針的擴展 GPIO 接頭。</p><p>然而，説到 USB 連接時，樹莓派 4 提供了兩個 USB 3.0 端口以及另外兩個 USB 2 端口。而樹莓派 3 只限於兩個 USB 2 端口。</p>',15)),a("p",null,[t[4]||(t[4]=r("因此，如果你需要更快的數據傳輸速度，USB 3.0 端口應該會有幫助。例如，如果你要使用任何 ",-1)),l(i,{href:"https://itsfoss.com/best-linux-media-server/"},{default:s(()=>[...t[3]||(t[3]=[r("媒體服務器軟件",-1)])]),_:1}),t[5]||(t[5]=r("，這可以派上用場。",-1))]),t[23]||(t[23]=e('<p>除此之外，樹莓派 4 上還有 USB-C 的存在，如果 USB 配件需要，它可以用來給電路板供電（5V DC）。</p><h4 id="雙顯示器與相機支持" tabindex="-1">雙顯示器與相機支持 <a class="header-anchor" href="#雙顯示器與相機支持" aria-label="Permalink to “雙顯示器與相機支持”">​</a></h4><p>雖然樹莓派 3 提供了一個全尺寸的 HDMI 端口、DSI 端口和 CS 端口，但它並不具有雙顯示器支持。</p><p>有了樹莓派 4，你可以得到兩個微型 HDMI 端口，一個雙通道 DSI 端口和一個雙通道 CSI 攝像頭端口。</p><h3 id="你應該買哪一個" tabindex="-1">你應該買哪一個？ <a class="header-anchor" href="#你應該買哪一個" aria-label="Permalink to “你應該買哪一個？”">​</a></h3><div class="table-wrap"><table><thead><tr><th>規格</th><th>樹莓派 3</th><th>樹莓派 4</th></tr></thead><tbody><tr><td><strong>處理器</strong></td><td>四核 1.2GHz 博通 BCM2837</td><td>四核 1.5GHz 博通BCM2711</td></tr><tr><td><strong>RAM</strong></td><td>1 GB</td><td>高達 8 GB</td></tr><tr><td><strong>藍牙</strong></td><td>BLE</td><td>藍牙 5.0</td></tr><tr><td><strong>USB端口</strong></td><td>4 x USB 2.0</td><td>2 x USB 3.0，2 x USB 2.0</td></tr><tr><td><strong>無線連接</strong></td><td>是</td><td>是，2.4 GHz &amp; 5 GHz 頻段支持</td></tr><tr><td><strong>顯示端口</strong></td><td>1 x HDMI，1 x DSI</td><td>2 x micro-HDMI，1 個 DSI</td></tr><tr><td><strong>電源</strong></td><td>microUSB 和 GPIO，高達 2.5 A</td><td>5V DC，通過 USB-C 和GPIO（3 A）</td></tr><tr><td><strong>MicroSD 插槽</strong></td><td>是</td><td>是</td></tr><tr><td><strong>價格</strong></td><td>35 美元</td><td>35 美元（1 GB 內存）、45 美元（2 GB 內存）、55 美元（4 GB 內存）、75 美元（8 GB 內存）</td></tr></tbody></table></div><p>如果你想要更快的數據傳輸，支持雙顯示器，以及更好的性能，樹莓派 4 是一個很好的選擇。</p><p>考慮到 2GB 內存的樹莓派 4 基本型號的價格約為 35 美元。以幾乎相同的價格選擇 1GB 的樹莓派 3 型號，實在是毫無意義。</p><p>當然，除非你能得到一個更便宜的價格，並且有特定的要求。樹莓派 4 總體上是一個明確的選擇。</p><p>然而，有一些事情，如板子發熱和其他潛在的問題，你可能想在決定之前探討一下。樹莓派 3 已被證明能在許多項目中發揮作用，而樹莓派 4 是相當新的，可能還沒有經過各種項目的測試。</p><p>一旦你確定了這一點，你就可以繼續得到它們中的任何一個。</p><p>你喜歡用什麼？你都試過了嗎？請在下面的評論中告訴我們。</p><hr>',13)),a("p",null,[t[7]||(t[7]=r("via: ",-1)),l(i,{href:"https://itsfoss.com/raspberry-pi-3-vs-4/"},{default:s(()=>[...t[6]||(t[6]=[r("https://itsfoss.com/raspberry-pi-3-vs-4/",-1)])]),_:1})]),a("p",null,[t[12]||(t[12]=r("作者：",-1)),l(i,{href:"https://itsfoss.com/author/ankush/"},{default:s(()=>[...t[8]||(t[8]=[r("Ankush Das",-1)])]),_:1}),t[13]||(t[13]=r(" 選題：",-1)),l(i,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[9]||(t[9]=[r("lujun9972",-1)])]),_:1}),t[14]||(t[14]=r(" 譯者：",-1)),l(i,{href:"https://github.com/wxy"},{default:s(()=>[...t[10]||(t[10]=[r("wxy",-1)])]),_:1}),t[15]||(t[15]=r(" 校對：",-1)),l(i,{href:"https://github.com/wxy"},{default:s(()=>[...t[11]||(t[11]=[r("wxy",-1)])]),_:1})]),a("p",null,[t[18]||(t[18]=r("本文由 ",-1)),l(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[16]||(t[16]=[r("LCTT",-1)])]),_:1}),t[19]||(t[19]=r(" 原創編譯，",-1)),l(i,{href:"https://linux.cn/"},{default:s(()=>[...t[17]||(t[17]=[r("Linux中國",-1)])]),_:1}),t[20]||(t[20]=r(" 榮譽推出",-1))])])}const I=p(m,[["render",u]]);export{g as __pageData,I as default};
